//! Copy the golden matrix into the static site and write the catalog index.
//!
//! The matrix itself is generated by `tests/fmt_ron_matrix.rs` into
//! `test_data/fmt_ron_matrix/`. The matrix page is plain files under `www/`,
//! so this task keeps the copy there and derives `data/index.json` from it.

use crate::util::{ensure_dir, repo_root};
use serde_json::{Value, json};
use std::fs;
use std::path::Path;

pub fn run(args: &[String]) -> Result<(), String> {
    if !args.is_empty() {
        return Err("build-matrix-site takes no arguments".into());
    }
    let root = repo_root();
    let source = root.join("test_data").join("fmt_ron_matrix");
    let destination = root.join("www").join("matrix").join("data");

    if !source.is_dir() {
        return Err(format!(
            "{}: missing; run the fmt_ron_matrix test first",
            source.display()
        ));
    }
    ensure_dir(&destination)?;

    let mut rows: Vec<_> = fs::read_dir(&source)
        .map_err(|e| format!("{}: {e}", source.display()))?
        .filter_map(|entry| entry.ok().map(|entry| entry.path()))
        .filter(|path| path.extension().is_some_and(|ext| ext == "ron"))
        .collect();
    rows.sort();

    let expected: Vec<_> = rows
        .iter()
        .filter_map(|path| path.file_name().map(|name| name.to_owned()))
        .collect();
    for entry in
        fs::read_dir(&destination).map_err(|e| format!("{}: {e}", destination.display()))?
    {
        let path = entry.map_err(|e| e.to_string())?.path();
        let is_ron = path.extension().is_some_and(|ext| ext == "ron");
        let name = path.file_name().map(|name| name.to_owned());
        if is_ron && !name.as_ref().is_some_and(|name| expected.contains(name)) {
            fs::remove_file(&path).map_err(|e| format!("{}: {e}", path.display()))?;
        }
    }
    for path in &rows {
        let name = path.file_name().expect("file name");
        fs::copy(path, destination.join(name)).map_err(|e| format!("{}: {e}", path.display()))?;
    }

    let mut entries = Vec::new();
    for path in &rows {
        if path.file_name().is_some_and(|name| name == "manifest.ron") {
            continue;
        }
        entries.push(entry_for(path)?);
    }
    entries.sort_by(|a, b| {
        let key = |value: &Value| {
            (
                value["settings"].as_str().unwrap_or("").to_owned(),
                value["id"].as_str().unwrap_or("").to_owned(),
            )
        };
        key(a).cmp(&key(b))
    });
    let index = json!({ "entries": entries, "count": entries.len() });
    let index_path = destination.join("index.json");
    let mut text = serde_json::to_string(&index).map_err(|e| e.to_string())?;
    text.push('\n');
    fs::write(&index_path, text).map_err(|e| format!("{}: {e}", index_path.display()))?;
    println!("wrote {} ({} rows)", index_path.display(), entries.len());
    Ok(())
}

fn entry_for(path: &Path) -> Result<Value, String> {
    let text = fs::read_to_string(path).map_err(|e| format!("{}: {e}", path.display()))?;
    let settings = between(&text, "\n    settings: (", "\n    ),")
        .ok_or_else(|| format!("{}: not a matrix row", path.display()))?;
    let configs = between(&text, "\n    configs: [", "\n    ],")
        .ok_or_else(|| format!("{}: not a matrix row", path.display()))?;
    let names: Vec<String> = quoted(configs)
        .into_iter()
        .map(|name| unescape(&name))
        .collect();
    Ok(json!({
        "id": path.file_stem().and_then(|s| s.to_str()).unwrap_or(""),
        "file": path.file_name().and_then(|s| s.to_str()).unwrap_or(""),
        "configs": names,
        "settings": settings,
        "inputs_count": text.matches("\n            input: \"").count(),
        "failed_count": text.matches("result: Failed(").count(),
    }))
}

fn between<'a>(text: &'a str, start: &str, end: &str) -> Option<&'a str> {
    let begin = text.find(start)? + start.len();
    let rest = &text[begin..];
    let finish = rest.find(end)?;
    Some(&rest[..finish])
}

/// Double-quoted strings in the config list, leaving the escapes in place.
fn quoted(text: &str) -> Vec<String> {
    let bytes = text.as_bytes();
    let mut out = Vec::new();
    let mut i = 0;
    while i < bytes.len() {
        if bytes[i] != b'"' {
            i += 1;
            continue;
        }
        let start = i + 1;
        i = start;
        while i < bytes.len() {
            match bytes[i] {
                b'\\' => i += 2,
                b'"' => break,
                _ => i += 1,
            }
        }
        out.push(String::from_utf8_lossy(&bytes[start..i.min(bytes.len())]).into_owned());
        i += 1;
    }
    out
}

/// Undo the RON string escapes that can appear in config names.
fn unescape(value: &str) -> String {
    serde_json::from_str(&format!("\"{value}\"")).unwrap_or_else(|_| value.to_owned())
}
